const CASTING_DIFFICULTIES=[{name:'Easy',dc:4},{name:'Advanced',dc:6},{name:'Hard',dc:8},{name:'Very Hard',dc:10},{name:'Improbable',dc:12},{name:'Inconceivable',dc:20},{name:'Impossible',dc:100}];

