function renderPrefixes(){const root=$('#prefixGrid');root.replaceChildren();Object.entries(PREFIXES).forEach(([key,p])=>{const b=document.createElement('button');b.type='button';b.className='choice-card';b.dataset.key=key;b.disabled=!composerAllowsPrefixes()&&!selectedPrefixes.has(key);b.title=[t('Prefixes modify a Base Attack or an attack-like Shape.'),...p.effects.map(effect=>t(effect)),key==='knockback'?t('On a failed enemy Brace, knock the target back Potential × 5 m. The normal damage chain is unchanged.'):''].filter(Boolean).join(' ');b.setAttribute('aria-pressed',String(selectedPrefixes.has(key)));b.innerHTML=`<strong>${t(p.label)}</strong><span>1 AP · ${p.potential?`+${p.potential} ${t('potential')}`:t('multi-target')}</span>`;b.onclick=()=>{selectedPrefixes.has(key)?selectedPrefixes.delete(key):selectedPrefixes.add(key);renderComposer()};root.append(b)})}
function selectedWordData(){const out=[];for(const cat of Object.keys(WORDS))for(const w of WORDS[cat])if(selectedWords.has(`${cat}:${w.id}`))out.push({...w,category:cat});return out}
function renderWords(){const root=$('#wordCategories');root.replaceChildren();for(const [cat,words] of Object.entries(WORDS)){const sec=document.createElement('section');sec.className='word-category';const h=document.createElement('h3');h.textContent=t(cat==='source'?'Sources':cat==='shape'?'Shapes':'Mastery');const grid=document.createElement('div');grid.className='word-grid';words.forEach(w=>{const key=`${cat}:${w.id}`,b=document.createElement('button');b.type='button';b.className='word-button';b.setAttribute('aria-pressed',String(selectedWords.has(key)));b.innerHTML=`<strong>${t(w.name)}</strong><b>${w.word}</b><small>${w.mana?`${w.mana} ${t('Mana')}`:w.dust?`${w.dust} ${t('Dust')}`:t('No energy')}</small>`;b.title=[...(Array.isArray(w.effects)?w.effects:Object.values(w.effects)),w.interactions].map(t).join(' ');b.onclick=()=>{selectedWords.has(key)?selectedWords.delete(key):selectedWords.add(key);renderComposer();renderWords()};grid.append(b)});sec.append(h,grid);root.append(sec)}}
function resolveWordComposition(words,hasBaseAttack){
  const sources=words.filter(x=>x.category==='source'),shapes=words.filter(x=>x.category==='shape'),mastery=words.filter(x=>x.category==='mastery');
  const primaries=shapes.filter(x=>x.delivery==='primary-attack'),primary=primaries[0]||null,containers=shapes.filter(x=>x.delivery==='container'||x.delivery==='area');
  const hearing=mastery.find(x=>x.delivery==='mastery-hearing'),diagnostics=[];
  if(primaries.length>1)diagnostics.push(t('Competing primary delivery Shapes: {selected}. Tracker ruling: {winner} wins by stable catalog priority; the others modify the endpoint only where their interaction permits.',{selected:primaries.map(x=>t(x.name)).join(', '),winner:t(primary.name)}));
  if(shapes.some(x=>['spiral','flat'].includes(x.id))&&shapes.length===1)diagnostics.push(t('{shape} requires another Shape to modify.',{shape:t(shapes[0].name)}));
  if(sources.some(x=>x.id==='echoes')&&words.length===1)diagnostics.push(t('Echoes requires an identifiable earlier spell trace; choose one at the table.'));
  let mode='touch';if(hasBaseAttack)mode='smite';else if(primary)mode='attack';else if(containers.length)mode='area';
  let delivery,targets,resolution;
  if(hasBaseAttack){delivery=t('Weapon or unarmed hit carries the selected Sources.');targets=t('One attack target; weapon range applies.');resolution=t('Roll weapon accuracy. Source Smite is part of that hit.');}
  else if(hearing){delivery=t('Power Word delivers the payload through hearing.');targets=t('Anything that can hear within audible reach; compatible Shapes manifest on each listener.');resolution=t('Targets use area resistance; no spell-accuracy roll unless a carried primary Shape specifically attacks one target.');}
  else if(primary){delivery=t('{shape} is the primary delivery: {target}, range {range}.',{shape:t(primary.name),target:t(primary.target),range:t(primary.range)});targets=containers.length?t('Attack the primary target, then place {areas} at the target or impact point; occupants in those footprints are also affected.',{areas:containers.map(x=>`${t(x.name)} (${t(x.area)})`).join(', ')}):t('{target}; {area}.',{target:t(primary.target),area:t(primary.area)});resolution=containers.length?t('Roll spell accuracy for the primary target. Other occupants of a manifested area use resistance DC {difficulty} {dc}.',{difficulty:t(CASTING_DIFFICULTIES[Math.min(words.length-1,CASTING_DIFFICULTIES.length-1)].name),dc:CASTING_DIFFICULTIES[Math.min(words.length-1,CASTING_DIFFICULTIES.length-1)].dc}):t('Roll spell accuracy against the primary target’s defense.');}
  else if(containers.length){const difficulty=CASTING_DIFFICULTIES[Math.min(words.length-1,CASTING_DIFFICULTIES.length-1)];delivery=t('Area/container Shapes place the payload directly; no attack roll.');targets=containers.map(x=>`${t(x.name)}: ${t(x.area)}, ${t(x.range)}, ${t(x.duration)}`).join(' · ');resolution=t('Each affected target makes area resistance at {difficulty} {dc}. Resistance difficulty uses total selected Word count ({count}), not AP or prefix count.',{difficulty:t(difficulty.name),dc:difficulty.dc,count:words.length});}
  else{delivery=t('Somatic touch delivers an unshaped Source or utility Word.');targets=t('One touched target.');resolution=t('Willing target: no roll. Harmful use follows target defense or resistance as agreed at the table.');}
  return {sources,shapes,mastery,primaries,primary,containers,mode,diagnostics,delivery,targets,resolution,hasArea:!!hearing||containers.length>0};
}
function renderComposer(){renderPrefixes();const words=selectedWordData(),hasAttackShape=composerHasAttackShape(words),hasBaseAttack=composerHasBaseAttack(words);const resolved=resolveWordComposition(words,hasBaseAttack);const c=getCharacter($('#composerCharacter')?.value),w=hasBaseAttack?selectedWeapon():null;const prefixKeys=Object.keys(PREFIXES).filter(k=>selectedPrefixes.has(k));const invalidPrefixes=prefixKeys.length>0&&!composerAllowsPrefixes();const hasAction=hasBaseAttack||words.length>0;const valid=hasAction&&!invalidPrefixes;const isSmite=hasBaseAttack&&words.length===1&&words[0].category==='source';const wordAp=words.length-(isSmite?1:0);const ap=(hasBaseAttack?1:0)+prefixKeys.length+wordAp;const basePotential=hasBaseAttack?BASE_ATTACK_POTENTIAL:0;const mana=words.reduce((s,x)=>s+(x.mana||0),0),dust=words.reduce((s,x)=>s+(x.dust||0),0);const prefixPotential=prefixKeys.reduce((s,k)=>s+PREFIXES[k].potential,0);const potential=basePotential+mana+dust+prefixPotential;
  $('#composerWeapon').disabled=!hasBaseAttack;const baseButton=$('#includeAttackButton');baseButton.disabled=hasAttackShape;baseButton.setAttribute('aria-pressed',String(hasBaseAttack));baseButton.classList.toggle('active',hasBaseAttack);
  const baseNote=hasAttackShape?t('Attack-like Shapes replace Base Attack: no base AP/potential, weapon accuracy/Impact, or Smite discount.')+' '+t(includesBaseAttack?'Remove the last attack-like Shape to restore your saved Base Attack: on.':'Remove the last attack-like Shape to restore your saved Base Attack: off.'):t('Base Attack preference is remembered while attack-like Shapes replace it.');baseButton.title=baseNote;$('#baseAttackNote').textContent=baseNote;
  const readable=x=>t(x.id==='thunder'&&x.category==='source'?'Lightning':x.name);const parts=prefixKeys.map(k=>t(PREFIXES[k].label));if(hasBaseAttack){parts.push(w?t('Weapon Attack ({weapon})',{weapon:t(w.name)}):t('Attack'));if(resolved.sources.length)parts.push(t('of {sources}',{sources:resolved.sources.map(readable).join('/')}));parts.push(...words.filter(x=>x.category!=='source').map(readable))}else parts.push(...words.map(readable));
  $('#actionName').textContent=invalidPrefixes?t('Choose an attack for these prefixes'):parts.join(' ')||t('Choose components');const incantation=[...prefixKeys.map(k=>PREFIXES[k].word),...words.map(x=>x.word)].join(' ');$('#actionIncantation').hidden=!valid||!incantation;$('#actionIncantation').textContent=valid&&incantation?t('Alternative incantation (tracker flavor, not canonical): {name}',{name:incantation}):'';
  let accuracy='—';if(w)accuracy=c?`${w.accuracy} d${c.current[w.accuracy]}`:w.accuracy;else if(!hasBaseAttack&&resolved.primary){const spellAttr=c&&idx(c.current.AUR)>idx(c.current.INT)?'AUR':'INT';accuracy=c?`${spellAttr} d${c.current[spellAttr]}`:t('INT or AUR, whichever is higher')}else if(!hasBaseAttack&&resolved.hasArea)accuracy=t('Area resistance');
  const metrics=[['AP',valid?ap:'—'],['Potential',valid?potential:'—'],['Accuracy',valid?accuracy:'—']];$('#actionMetrics').replaceChildren(...metrics.map(([k,v])=>{const d=document.createElement('div');d.className='metric';d.innerHTML=`<span>${t(k)}</span><strong>${v}</strong>`;return d}));
  const effects=[];if(invalidPrefixes)effects.push(t('Prefixes need a Base Attack or an attack-like Shape. Add one, or remove the prefixes; no totals are shown until then.'));if(valid&&w)effects.push(t('Impact: {value}.',{value:w.impact??6}));for(const k of valid?prefixKeys:[])effects.push(...PREFIXES[k].effects.map(effect=>t(effect)));if(valid&&selectedPrefixes.has('dashing'))effects.push(t('Dashing movement: up to {meters} m.',{meters:potential*5}));if(valid&&selectedPrefixes.has('knockback'))effects.push(t('On a failed enemy Brace, knock the target back {meters} m (Potential × 5). The normal damage chain is unchanged.',{meters:potential*5}));if(valid&&hasBaseAttack&&resolved.sources.length>1)effects.push(t('Multiple Sources in a weapon or unarmed combination each cost 1 AP; slash-separated names do not grant a Smite discount.'));if(valid&&words.length){effects.push(`${t('Resources')}: ${[mana?`${mana} ${t('Mana')}`:'',dust?`${dust} ${t('Dust')}`:''].filter(Boolean).join(' · ')||t('None')}`);effects.push(t('Tracker ruling: potential = base {base} + prefixes {prefixes} + Mana {mana} + Dust {dust} = {total}.',{base:basePotential,prefixes:prefixPotential,mana,dust,total:potential}));const energy=mana+dust;if(energy>=3){let i=Math.min(energy-3,CASTING_DIFFICULTIES.length-1);if(resolved.mastery.some(x=>x.id==='hold'))i=Math.max(0,i-1);effects.push(`${t('Caster casting check')}: ${t(CASTING_DIFFICULTIES[i].name)} ${CASTING_DIFFICULTIES[i].dc}`)}else effects.push(t('Caster casting check: none (fewer than 3 energy spent).'));if(isSmite)effects.push(t('Source Smite costs Mana but no additional AP.'))}if(valid&&ap>3)effects.push(t('{turns}-turn action; charge before release.',{turns:Math.ceil(ap/3)}));$('#actionEffects').replaceChildren(...effects.map(x=>{const li=document.createElement('li');li.textContent=x;return li}));
  const setText=(id,text)=>{const node=$(id);if(node)node.textContent=valid?text:'—'};setText('#deliverySummary',resolved.delivery);setText('#targetsSummary',resolved.targets);setText('#resolutionSummary',resolved.resolution);
  const setList=(id,items)=>{const node=$(id);if(node)node.replaceChildren(...items.map(x=>{const li=document.createElement('li');li.textContent=t(x);return li}))};setList('#sourceEffects',valid?resolved.sources.map(x=>`${t(x.name)}: ${t(x.effects[resolved.mode]||x.effects.touch)} ${t('Duration')}: ${t(x.duration)} ${t('Tracker ruling.')}`):[]);setList('#shapeInteractions',valid?resolved.shapes.map(x=>`${t(x.name)}: ${t(x.interactions)}`):[]);setList('#masteryEffects',valid?resolved.mastery.flatMap(x=>[...x.effects.map(effect=>`${t(x.name)}: ${t(effect)}`),`${t(x.name)} — ${t(x.interactions)}`]):[]);setList('#composerDiagnostics',resolved.diagnostics);
}

function setView(view,explicit=true){ui.view=view;save();syncView(explicit)}
function syncView(explicit=false){const mobile=matchMedia('(max-width:760px)').matches;const single=state.characters.length===1;let view=ui.view==='detail'?'detail':ui.view;if(mobile&&single&&view==='roster')view='detail';rosterPane.hidden=view!=='roster'&&!(view==='detail'&&!mobile);detailPane.hidden=view!=='detail'&&view!=='roster';actionPane.hidden=view!=='action';guidePane.hidden=view!=='guide';document.body.classList.toggle('single-character',single);if(mobile){rosterPane.classList.toggle('mobile-hidden',view!=='roster');detailPane.classList.toggle('mobile-hidden',view!=='detail')}else{rosterPane.classList.remove('mobile-hidden');detailPane.classList.remove('mobile-hidden')}
  document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===((view==='detail'||(single&&ui.view==='roster'))?'roster':view)));$('#headerTitle').textContent=t(view==='action'?'Action Composer':view==='guide'?'Combat Guide':view==='detail'?(getCharacter()?.name||'Character'):'Roster');if(explicit)window.scrollTo({top:0,behavior:'auto'})}

function removeCharacter(c){if(!c||!confirm(t('Remove {name} from roster?',{name:c.name})))return;state.characters=state.characters.filter(x=>x.id!==c.id);if(ui.selectedId===c.id)ui.selectedId=state.characters[0]?.id||null;if(!state.characters.length)ui.view='roster';save();renderAll();}
function openCharacterDialog(){const tpl=TEMPLATES[0];populateCreator(tpl);characterDialog.showModal()}
function populateCreator(tpl){$('#newCharacterName').value=tpl.id==='blank'?'':t(tpl.name);$('#newCharacterCount').value='1';const root=$('#newCharacterStats');root.replaceChildren();ATTRIBUTES.forEach((a,i)=>{const s=selectDice(tpl.stats[i]);s.name=a;root.append(equipmentField(a,s))});$('#templateGrid').querySelectorAll('.template-button').forEach(b=>b.classList.toggle('active',b.dataset.id===tpl.id))}
function renderTemplates(){const root=$('#templateGrid');root.replaceChildren(...TEMPLATES.map(tpl=>{const b=document.createElement('button');b.type='button';b.className='template-button';b.dataset.id=tpl.id;b.innerHTML=`<strong>${t(tpl.name)}</strong><span>${tpl.stats.map(x=>`d${x}`).join(' · ')}</span>`;b.onclick=()=>populateCreator(tpl);return b}))}

$('#addButton').onclick=openCharacterDialog;$('#rosterAddButton').onclick=openCharacterDialog;$('#cancelCharacterButton').onclick=()=>characterDialog.close();
$('#characterForm').addEventListener('submit',e=>{e.preventDefault();const base=$('#newCharacterName').value.trim()||t('Character');const count=Math.min(20,Math.max(1,Number($('#newCharacterCount').value)||1));const maximum={};ATTRIBUTES.forEach(a=>maximum[a]=Number(e.target.elements[a].value));for(let i=0;i<count;i++){const name=count>1?`${base} ${i+1}`:base;state.characters.push(normalizeCharacter({name,initiative:0,maximum,current:{...maximum},pending:{},equipment:newEquipment()}))}if(!ui.selectedId)ui.selectedId=state.characters[0]?.id||null;save();characterDialog.close();renderAll()});
$('#sortInitiativeButton').onclick=()=>{ui.sortInitiative=!ui.sortInitiative;save();$('#sortInitiativeButton').textContent=t(ui.sortInitiative?'Use roster order':'Sort initiative');renderRoster()};
$('#endRoundButton').onclick=()=>{if(!state.characters.some(hasPending))return;if(!confirm(t('Apply all pending wounds?')))return;state.characters.forEach(c=>ATTRIBUTES.forEach(a=>{c.current[a]=stepDown(c.current[a],c.pending[a]||0);c.pending[a]=0}));save();renderAll()};
$('#backToRosterButton').onclick=()=>setView('roster',true);$('#detailEndRoundButton').onclick=()=>$('#endRoundButton').click();$('#fullHpButton').onclick=()=>{const c=getCharacter();if(!c||!confirm(t('Reset to full HP, clear pending wounds, and remove death? This is a GM override, not a rest.')))return;ATTRIBUTES.forEach(a=>{c.current[a]=c.maximum[a];c.pending[a]=0});c.dead=false;save();renderAll()};
$('#toggleStatEditButton').onclick=()=>{editMaximums=!editMaximums;renderDetail()};
$('#addWeaponButton').onclick=()=>{const c=getCharacter();if(!c)return;c.equipment.weapons.push({name:t('Weapon'),weaponClass:'light',accuracy:'STR',impact:6,equipped:true});save();renderDetail();renderComposerCharacters()};
$('#addArmorButton').onclick=()=>{const c=getCharacter();if(!c)return;c.equipment.plating.push({type:'medium',equipped:true});save();renderDetail()};
$('#deleteCharacterButton').onclick=()=>removeCharacter(getCharacter());
$('#composerCharacter').onchange=()=>{const id=$('#composerCharacter').value;if(id){ui.selectedId=id;save();renderRoster();renderDetail()}renderComposerWeapons();renderComposer()};$('#composerWeapon').onchange=renderComposer;$('#includeAttackButton').onclick=()=>{includesBaseAttack=!includesBaseAttack;renderComposer()};$('#clearComposerButton').onclick=()=>{selectedPrefixes.clear();selectedWords.clear();renderWords();renderComposer()};$('#clearWordsButton').onclick=()=>{selectedWords.clear();renderWords();renderComposer()};
document.querySelectorAll('.nav-button').forEach(b=>b.onclick=()=>setView(b.dataset.view,true));localeSelect.onchange=()=>{locale=localeSelect.value;localStorage.setItem(LOCALE_KEY,locale);applyLocale();renderTemplates();renderWords()};
matchMedia('(max-width:760px)').addEventListener('change',()=>syncView(false));

captureLocale(document.documentElement);localeSelect.value=locale;applyLocale();renderTemplates();renderWords();renderAll(false);
